insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('e17e4917-db52-56ee-9916-7d9f4ed5ac76', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', '$3x + 5y = 21$
$y = 3$
What is the solution $(x,y)$ to the given system of equations?', '["$(3,7)$", "$(3, \\frac{7}{3})$", "$(\\frac{8}{5},3)$", "$(2,3)$"]'::jsonb, 1, null),
  ('3ea7a1dd-8be5-569a-a485-fc118a079506', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', '$(v - 12)(v - 3) = 0$
What are all possible solutions to the given equation?', '["$-12$ and $3$", "$-12$ and $9$", "$-3$ and $12$", "$3$ and $12$"]'::jsonb, 2, null),
  ('8ccd7c4a-b529-5f7b-bad0-b028eccbbfec', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The function $f$ is defined by $f(x) = 135x - 20$. What is the value of $f(x)$ when $x = 4$?', '[]'::jsonb, 3, null),
  ('87ea8a3c-af2d-5085-8df4-e049b60abff8', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'For the linear function $f$, the graph of $y = f(x)$ in the $xy$-plane has a slope of $51$ and passes through the point $(0,0)$. Which equation defines $f$?', '["$f(x) = 51x$", "$f(x) = 34x$", "$f(x) = 17x$", "$f(x) = x$"]'::jsonb, 4, null),
  ('dad91a40-b7ca-526f-9a4d-5aae625ba8bc', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'In the figure shown, line $m$ is parallel to line $n$, and line $k$ intersects both lines. Which of the following statements is true?', '["$q = 135$", "$r = 135$", "$s = 135$", "$t = 135$"]'::jsonb, 5, '![figure](/q/jun24/001.webp)'),
  ('346190fe-a806-5711-b1d1-300fde30446a', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The function $f$ is defined by $f(x) = -5x^{2} - 7$. What is the value of $f(-1)$?', '["$-12$", "$-2$", "$2$", "$12$"]'::jsonb, 6, null),
  ('e38a1277-7d09-56a3-a472-34d6002dfa82', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', '$y = -0.5$
$y = x^{2} + 10x + a$
In the given system of equations, $a$ is a positive integer constant. The system has no real solutions. What is the least possible value of $a$?', '[]'::jsonb, 7, null),
  ('1c31b476-a996-5012-a359-a536433bcae4', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The expression $(6x^{2})(3x^{7})$ is equivalent to $bx^{9}$, where $b$ is a constant. What is the value of $b$?', '[]'::jsonb, 8, null),
  ('7145e385-3753-5152-a356-b998a51db2eb', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'A teacher is creating an assignment worth $28$ points. The assignment will consist of questions worth $1$ point and questions worth $2$ points. Which equation represents this situation, where $x$ represents the number of $1$-point questions and $y$ represents the number of $2$-point questions?', '["$3x + y = 28$", "$3(x + y) = 28$", "$2x + y = 28$", "$x + 2y = 28$"]'::jsonb, 9, null),
  ('0c406c16-7ae1-5d0a-b30d-e236408ea144', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown. Which of the following is closest to the slope of the line of best fit shown?', '["$10.95$", "$0.79$", "$-0.79$", "$-10.95$"]'::jsonb, 10, '![figure](/q/jun24/002.webp)'),
  ('6b1ebbc1-ccfa-5f24-8e2a-0a8c978dc647', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'Triangle $XY Z$ shown is a right triangle. Which of the following has the same value as $\sin X$?', '["$\\cos Y$", "$\\cos X$", "$\\tan Y$", "$\\tan X$"]'::jsonb, 11, '![figure](/q/jun24/003.webp)'),
  ('0cad5653-5807-574b-9082-3359cf1f8b2e', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'Sam opened a savings account at a bank. The table shows the exponential relationship between the time $t$, in years, since Sam opened the account and the total amount $n$, in dollars, in the account. If Sam made no additional deposits or withdrawals, which of the following equations best represents the relationship between $t$ and $n$?', '["$n = 0.004(1 + 867)^{t}$", "$n = 867(1 + 0.004)^{t}$", "$n = (1 + 0.004)^{t}$", "$n = (1 + 867)^{t}$"]'::jsonb, 12, '| Time (years) | Total amount (dollars) |
| 0 | 867.00 |
| 1 | 870.47 |
| 2 | 873.95 |'),
  ('64e0d49c-5ee4-52d8-bcfb-3db62099be35', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'If $6(8 - 2x) + 3 = 5(8 - 2x) + 19$, what is the value of $8 - 2x$?', '["$-16$", "$-4$", "$4$", "$16$"]'::jsonb, 13, null),
  ('b59fb13e-80f5-5c3d-8cf0-88865083d95c', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The table shows four values of $a$ and their corresponding values of $y$. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?', '["$24x + 6y = 46$", "$24x + 6y = 276$", "$6x + 24y = 46$", "$6x + 24y = 276$"]'::jsonb, 14, '| x | y |
| -12 | 94 |
| -6 | 70 |
| 6 | 22 |
| 12 | -2 |'),
  ('865a627a-7f36-5a2a-a19f-54c27de5f41a', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', '$y = 2x^{2} - 19x + 40$
$y = x + a$
In the given system of equations, $a$ is a constant. The graphs of the equations in the given system intersect at exactly one point, $(x,y)$, in the $xy$-plane. What is the value of $x$?', '["$-10$", "$-5$", "$5$", "$10$"]'::jsonb, 15, null),
  ('6dd67ba1-2eb4-59c9-a9b6-4fc3373867ad', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'Line $p$ in the $xy$-plane is defined by $y = x + \frac{5}{9}$ and passes through the points $(a,0)$ and $(0,b)$, where $a$ and $b$ are constants. What is the value of $a$?', '[]'::jsonb, 16, null),
  ('02c3f8d4-63bc-5063-92ca-ee6df09ec9b7', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The function $f(t) = 80,000(2)\frac{t}{790}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?', '["$2$", "$790$", "$1,580$", "$80,000$"]'::jsonb, 17, null),
  ('074bcab1-7e5e-5ce2-8f4b-b82326f70fcb', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'Square P has a side length of $x$ inches. Square Q has a perimeter that is $32$ inches greater than the perimeter of square P. The function $f$ gives the area of square Q, in square inches. Which of the following defines $f$?', '["$f(x) = (x + 8)^{2}$", "$f(x) = (x + 32)^{2}$", "$f(x) = (32x + 8)^{2}$", "$f(x) = (32x + 32)^{2}$"]'::jsonb, 18, null),
  ('7ac56b4c-97cd-5196-b455-93a39de4a678', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', '$3.5x + 1.2y = 8$
$17.5x + 6y = 40$
How many solutions does the given system of equations have?', '["Exactly one", "Exactly two", "Infinitely many", "Zero"]'::jsonb, 19, null),
  ('ea8b07f5-df4d-582a-8e8b-8c93022f24a0', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'Circle $A$ has a radius of $2x$ and circle $B$ has a radius of $94x$. The area of circle $B$ is how many times the area of circle $A$?', '[]'::jsonb, 20, null),
  ('88b761b9-ffbe-5ea7-aec8-127256038a12', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'The function $g$ is defined by $g(x) = (x + 17)(t - x)$, where $t$ is a constant. In the $xy$-plane, the graph of $y = g(x)$ passes through the point $(23,0)$. What is the value of $g(0)$?', '[]'::jsonb, 21, null),
  ('bd7f3b15-3790-527b-b447-cfe661623334', '9bf9b6d0-a285-5cf1-b6c6-f59ecb08a8b8', 'A circle in the $xy$-plane has a diameter with endpoints $(a,11)$ and $(a,d)$, where $a$ and $d$ are constants. An equation of this circle is $(x - a)^{2} + (y - 17)^{2} = r^{2}$, where $r$ is a positive constant. What is the value of $d$?', '["$5$", "$12$", "$17$", "$23$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('e17e4917-db52-56ee-9916-7d9f4ed5ac76', 3, null, '**Choice D is correct.** Substitute $y = 3$ into $3x + 5y = 21$ to get $3x + 5(3) = 21$, so $3x + 15 = 21$. Solving gives $3x = 6$ and $x = 2$, so the solution is $(2,3)$.
**Choice A is incorrect.** $(3,7)$ has $y = 7$, which does not satisfy $y = 3$ and also would give $3(3) + 5(7) = 9 +$ $35 = 44 \ne 21$.
**Choice B is incorrect.** $(3, \frac{7}{3})$ has $y = \frac{7}{3} \ne 3$, so it violates the second equation; substituting into the first also fails.
**Choice C is incorrect.** $(\frac{8}{5},3)$ has $y = 3$ but $3(\frac{8}{5}) + 5(3) = \frac{24}{5} + 15 = \frac{24+75}{5} = \frac{99}{5} \ne 21$, so it does not satisfy the first equation.
**Faster approach:** Use direct substitution for systems given in the form $y = \text{expression}$; plug the given $y$ into the other equation and solve for $x$.'),
  ('3ea7a1dd-8be5-569a-a485-fc118a079506', 3, null, '**Choice D is correct.** The zero-product property says that if $(v - 12)(v - 3) = 0$, then either $v - 12 = 0$ or $v - 3 = 0$. Solving each gives $v = 12$ or $v = 3$, so the solutions are $3$ and $12$, which is Choice D.
**Choice A is incorrect.** The values $-12$ and $3$ include $3$ but do not include $12$; $-12$ does not satisfy either factor $v - 12$ or $v - 3$ equals zero.
**Choice B is incorrect.** Neither $-12$ nor $9$ makes $v - 12$ or $v - 3$ equal to zero, so they are not solutions of the equation.
**Choice C is incorrect.** $-3$ does not make either factor zero, and while $12$ is a solution, $-3$ is not, so this pair is wrong.
**Faster approach:** Use the zero-product property immediately: set each factor equal to zero ($v - 12 = 0$, $v -$ $3 = 0$) and read off the solutions $v = 12$ and $v = 3$. This works for any factored quadratic set equal to zero.'),
  ('8ccd7c4a-b529-5f7b-bad0-b028eccbbfec', null, array['520']::text[], '**The correct answer is 520.** To find $f(4)$, substitute $x = 4$ into the definition $f(x) = 135x - 20$. This gives
$f(4) = 135(4) - 20 = 540 - 20 = 520.$
**Faster approach:** Perform the multiplication $135 \times 4$ first (noting $135 \times 2 = 270$, so doubled is $540$), then subtract $20$ to get $520$. For similar linear-evaluation problems, directly substitute and carry out the simple arithmetic in that order.'),
  ('87ea8a3c-af2d-5085-8df4-e049b60abff8', 0, null, '**Choice A is correct.** A linear function with slope $51$ and passing through $(0,0)$ has equation $f(x) = mx + b$ with $m = 51$ and $b = 0$, so $f(x) = 51x$.
**Choice B is incorrect.** $f(x) = 34x$ has slope $34$, not $51$, so it does not match the given slope.
**Choice C is incorrect.** $f(x) = 17x$ has slope $17$, not $51$, so it is not the correct function.
**Choice D is incorrect.** $f(x) = x$ has slope $1$, not $51$, so it does not satisfy the slope condition.
**Faster approach:** For any line through the origin, the equation is $f(x) = mx$; the slope given is the coefficient $m$, so directly write $f(x) = 51x$.'),
  ('dad91a40-b7ca-526f-9a4d-5aae625ba8bc', 2, null, '**Choice C is correct.** Angle s is the vertical (opposite) angle to the marked 135° at the intersection of line k and line n. Vertical angles formed by two intersecting lines are congruent, so s = 135°.
**Choice A is incorrect.** Angle q is not vertical to the 135° angle; q lies at the intersection of k with the parallel line m. q and the 135° angle are on the same side of the transversal but on different parallel lines (consecutive interior), so they are supplementary. Thus q = 180° − 135° = 45°, not 135°.
**Choice B is incorrect.** Angle r is adjacent to the 135° angle at the intersection with n, so r and 135° are a linear pair and sum to 180°. Therefore r = 180° − 135° = 45°, not 135°.
**Choice D is incorrect.** Angle t is at the intersection of k with m in the position corresponding to r (or supplementary to q), so like q and r it equals 45° (not 135°) because corresponding/interior relationships with the 135° produce its supplement.
**Faster approach:** Identify which angle is at the same intersection as the given 135°; the angle directly opposite (vertical angle) is equal. For any transversal/parallel-lines problem, first check vertical-angle pairs at the same intersection before using corresponding or supplementary relations.'),
  ('346190fe-a806-5711-b1d1-300fde30446a', 0, null, '**Choice A is correct.** To evaluate $f(-1)$, substitute $x = -1$ into $f(x) = -5x^{2} - 7$. This gives $f(-1) =$ $-5(-1)^{2} - 7 = -5(1) - 7 = -5 - 7 = -12$, so $-12$ is the value of $f(-1)$.
**Choice B is incorrect.** $-2$ would result from $-5(-1)^{2} + 3$, not from the given expression; substituting correctly yields $-12$, not $-2$.
**Choice C is incorrect.** $2$ has the wrong sign and magnitude; the quadratic term $-5x^{2}$ is negative for $x = -1$, so the result cannot be positive $2$.
**Choice D is incorrect.** $12$ is the opposite sign of the correct value; the function evaluates to a negative number when $x = -1$.
**Faster approach:** Direct substitution: replace $x$ with $-1$, compute $(-1)^{2} = 1$, then multiply and add to get the result—this quick plug-in works for any evaluation of a given formula.'),
  ('e38a1277-7d09-56a3-a472-34d6002dfa82', null, array['25']::text[], '**The correct answer is 25.** To determine the least possible value of $a$ such that the system of equations has no real solutions, we need to analyze when the quadratic equation has no real roots.
Given the equation:
$y = x^{2} + 10x + a$
we can substitute $y = -0.5$ to form a new equation:
$-0.5 = x^{2} + 10x + a$
Rearranging this gives us:
$x^{2} + 10x + (a + 0.5) = 0$
This is a standard quadratic equation of the form $Ax^{2} + Bx + C = 0$, where $A = 1$, $B = 10$, and $C = a + 0.5$.
For a quadratic equation to have no real solutions, the discriminant must be less than zero. The discriminant $D$ is given by:
$D = B^{2} - 4AC$
Substituting our values for $A$, $B$, and $C$:
$D = 10^{2} - 4(1)(a + 0.5)$
This simplifies to:
$D = 100 - 4(a + 0.5)$
Expanding the equation gives:
$D = 100 - 4a - 2$
which further simplifies to:
$D = 98 - 4a$
To ensure there are no real solutions, set the discriminant less than zero:
$98 - 4a < 0$
Solving for $a$ yields:
$98 < 4a$
Dividing both sides by 4:
$24.5 < a$
Since $a$ must be a positive integer, the smallest integer greater than $24.5$ is $25$. Therefore, the least possible value of $a$ such that the system has no real solutions is:
$a = 25$'),
  ('1c31b476-a996-5012-a359-a536433bcae4', null, array['18']::text[], '**The correct answer is 18.** Multiply the numerical coefficients and add exponents on like bases. $(6x^{2})(3x^{7}) =$ $6 \cdot 3 \cdot x^{2+7} = 18x^{9}$, so $b = 18$.
**Faster approach:** Recognize the rule $a^{m} \cdot a^{n} = a^{m+n}$ and multiply the constants first: $6 \times 3 = 18$, then add exponents $2 + 7 = 9$, giving $18x^{9}$ immediately. This method works for any product of monomials with the same base.'),
  ('7145e385-3753-5152-a356-b998a51db2eb', 3, null, '**Choice D is correct.** Let $x$ be the number of 1-point questions and $y$ the number of 2-point questions. The total points equal the number of 1-point questions times 1 plus the number of 2-point questions times 2, so the equation is $1 \cdot x + 2 \cdot y = 28$, which is written as $x + 2y = 28$.
**Choice A is incorrect.** $3x + y = 28$ implies each 1-point question is counted as 3 points, which does not match the given point values.
**Choice B is incorrect.** $3(x + y) = 28$ implies each question is worth 3 points (or total questions times 3), which is not the situation.
**Choice C is incorrect.** $2x + y = 28$ swaps the point values, treating 1-point questions as worth 2 points and 2-point questions as worth 1 point, so it does not model the scenario.
**Faster approach:** Multiply each variable by its point value and add: $1x + 2y = 28$ immediately gives $x + 2y =$ $28$.'),
  ('0c406c16-7ae1-5d0a-b30d-e236408ea144', 2, null, '**Choice C is correct.** The line falls from about $y \approx 11$ at $x \approx 0$ to $y \approx 4$ at $x \approx 8$. The slope is approximately $\frac{4-11}{8-0} = \frac{-7}{8} \approx -0.875$, which is closest to $-0.79$.
**Choice A is incorrect.** A slope of $10.95$ is large and positive; the shown line is decreasing, so a positive value cannot be correct.
**Choice B is incorrect.** $0.79$ is positive, but the line clearly slopes downward, so the sign is wrong.
**Choice D is incorrect.** $-10.95$ is a very steep negative slope; the plotted line is only moderately negative (change of about -7 over 8 units), so this magnitude is far too large.
**Faster approach:** Pick two clear points on the line (for example near the left and right ends), compute slope $Δy/Δx$, and compare to choices—this yields the correct sign and nearest value quickly.'),
  ('6b1ebbc1-ccfa-5f24-8e2a-0a8c978dc647', 0, null, '**Choice A is correct.** In right triangle XYZ the right angle is at Z, so angles X and Y are complementary. For angle X, the side opposite is ZY (length 37) and the hypotenuse is XY, so $\sin X = \frac{37}{\text{hypotenuse}}$. For angle Y, the side adjacent is ZY (length 37), so $\cos Y = \frac{37}{\text{hypotenuse}}$. Thus $\sin X = \cos Y$.
**Choice B is incorrect.** $\cos X$ is the ratio of the adjacent side to angle X (XZ = 29) over the hypotenuse, which is $\frac{29}{\text{hypotenuse}}$, not equal to $\sin X$ here.
**Choice C is incorrect.** $\tan Y$ is opposite/adjacent for angle Y: opposite is XZ (29) and adjacent is ZY (37), so $\tan Y = \frac{29}{37}$, which does not equal $\sin X = \frac{37}{\text{hypotenuse}}$.
**Choice D is incorrect.** $\tan X$ is opposite/adjacent for angle X: $\tan X = \frac{37}{29}$, not equal to $\sin X$. **Faster approach:** Use complementary-angle identities in right triangles: for acute angles X and Y with X+Y=90°, $\sin X = \cos Y$ (so immediately choose A).'),
  ('0cad5653-5807-574b-9082-3359cf1f8b2e', 1, null, '**Choice B is correct.** The account grows exponentially with initial amount $n(0) = 867$, so the model must have form $n = 867 \cdot r^{t}$ for some growth factor $r$. From the table, $r = \frac{870.47}{867} = 1.004$ (since $870.47 - 867 =$ $3.47 \approx 0.004 \cdot 867$). Thus $n = 867(1.004)^{t}$, which matches choice B.
**Choice A is incorrect.** That expression has an incorrect structure: it multiplies $0.004$ by $(1 + 867)^{t}$ and does not place the initial amount $867$ as the base amount multiplied by the growth factor to the $t$ power.
**Choice C is incorrect.** That gives $n = (1.004)^{t}$ and omits the initial principal $867$, so it does not match the table values (for $t = 0$ it would give $1$, not $867$).
**Choice D is incorrect.** That uses $(1 + 867)^{t}$ which is a huge base and also omits multiplying by the initial amount correctly; it does not fit the given values.
**Faster approach:** Compute the year-to-year ratio $870.47/867 \approx 1.004$ to get the growth factor, then write
$t$
$n =$ initial amount $\times$(growth factor).'),
  ('64e0d49c-5ee4-52d8-bcfb-3db62099be35', 3, null, '**Choice D is correct.** Let $y = 8 - 2x$. Then the equation becomes $6y + 3 = 5y + 19$. Subtract $5y$ from both sides to get $y + 3 = 19$, so $y = 16$. Thus $8 - 2x = 16$, which matches choice D.
**Choice A is incorrect.** Substituting $8 - 2x = -16$ would give $6(-16) + 3 = -93$ on the left and $5(-16) +$ $19 = -61$ on the right, which are not equal.
**Choice B is incorrect.** Substituting $8 - 2x = -4$ yields $6(-4) + 3 = -21$ and $5(-4) + 19 = -1$, which are not equal.
**Choice C is incorrect.** Substituting $8 - 2x = 4$ gives $6(4) + 3 = 27$ and $5(4) + 19 = 39$, which are not equal.
**Faster approach:** Recognize the common binomial $8 - 2x$ and set it equal to a single variable $y$ to simplify immediately to a one-step linear equation $6y + 3 = 5y + 19$, then solve for $y$.'),
  ('b59fb13e-80f5-5c3d-8cf0-88865083d95c', 1, null, '**Choice B is correct.** The points show a constant slope: using (-12,94) and (-6,70), the slope is (70−94)/(-6− (−12)) = −24/6 = −4. So the line is $y = -4x + b$. Substituting (6,22) gives $22 = -4(6) + b$, so $b = 46$ and the equation is $y = -4x + 46$. Rearranging gives $4x + y = 46$, and multiplying both sides by 6 gives $24x + 6y =$ $276$, which matches choice B.
**Choice A is incorrect.** It corresponds to $4x + y = 46$ multiplied by 6 would give 276 on the right, not 46; A’s right-hand side is too small.
**Choice C is incorrect.** $6x + 24y = 46$ is not equivalent to $4x + y = 46$ (different coefficients and constant), so it does not fit the table.
**Choice D is incorrect.** $6x + 24y = 276$ does not simplify to $4x + y = 46$ and does not produce the correct y for the given x values.
**Faster approach:** Compute the slope from any two rows to get $m = -4$, find $b$ with one point to get $b = 46$, then rearrange to match the form of the answer choices (or multiply by a common factor to compare integers).'),
  ('865a627a-7f36-5a2a-a19f-54c27de5f41a', 2, null, '**Choice C is correct.** Substitute $y = x + a$ into $y = 2x^{2} - 19x + 40$ to get $2x^{2} - 20x + (40 - a) = 0$. For the two graphs to intersect at exactly one point, this quadratic must have a single (double) root, so the discriminant is zero: $(-20)^{2} - 4(2)(40 - a) = 0$. That gives $400 - 8(40 - a) = 0 ⇒ 400 - 320 + 8a = 0 ⇒$ $8a = -80 ⇒ a = -10$. Plugging $a = -10$ into the quadratic gives $2x^{2} - 20x + 50 = 0$, or $x^{2} - 10x + 25 =$ $0 = (x - 5)^{2}$, so $x = 5$.
**Choice A is incorrect.** $x = -10$ does not satisfy the double-root condition; substituting would not produce a perfect square factorization of the quadratic.
**Choice B is incorrect.** $x = -5$ is not the repeated root found when the discriminant is set to zero; the algebra gives $x = 5$ instead.
**Choice D is incorrect.** $x = 10$ is not a solution of the resulting repeated-root equation $(x - 5)^{2} = 0$ and thus not the intersection $x$-coordinate.
**Faster approach:** Set the line equal to the parabola, form the quadratic, and require the discriminant $b^{2} -$ $4ac = 0$ for exactly one intersection; then solve the resulting perfect-square quadratic for $x$.'),
  ('6dd67ba1-2eb4-59c9-a9b6-4fc3373867ad', null, array['-5/9']::text[], '**The correct answer is -5/9.** The line is given by $y = x + \frac{5}{9}$ and passes through $(a,0)$, so substituting $x = a$ and $y = 0$ gives $0 = a + \frac{5}{9}$. Solving for $a$ yields $a = -\frac{5}{9}$.
**Faster approach:** Immediately substitute $y = 0$ into the equation of the line and solve for $x$: $0 = x + \frac{5}{9} ⇒$ $x = -\frac{5}{9}$, which is the $x$-coordinate $a$ of the point $(a,0)$. This substitution method works for any similar question asking for a coordinate where one variable is 0.'),
  ('02c3f8d4-63bc-5063-92ca-ee6df09ec9b7', 1, null, '**Choice B is correct.** The population doubles when $f(t) = 2f(0)$. Since $f(0) = 80,000$, set $80,000 \cdot 2^{t/790} =$ $160,000$, so $2^{t/790} = 2^{1}$, giving $t/790 = 1$ and $t = 790$ minutes.
**Choice A is incorrect.** If $t = 2$, then $2^{t/790} = 2^{2/790}$, which is only slightly greater than 1, not equal to 2, so the population has not doubled.
**Choice C is incorrect.** If $t = 1,580$, then $2^{t/790} = 2^{2} = 4$, which would quadruple the initial population, not double it.
**Choice D is incorrect.** $t = 80,000$ would make the exponent $80,000/790$, producing a much larger factor than 2; it is not the doubling time.
**Faster approach:** Notice the base is 2, so the population doubles whenever the exponent increases by 1. Solve $t/790 = 1$ to get $t = 790$ minutes.'),
  ('074bcab1-7e5e-5ce2-8f4b-b82326f70fcb', 0, null, '**Choice A is correct.** Square P has perimeter $4x$. Square Q’s perimeter is $4x + 32$, so Q’s side length is $(4x +$ $32)/4 = x + 8$. The area of Q is the side squared, so $f(x) = (x + 8)^{2}$, which matches Choice A.
**Choice B is incorrect.** $(x + 32)^{2}$ would be the area if the side length increased by $32$, but the perimeter increased by $32$, not the side—so the side increases by $32/4 = 8$, not $32$.
**Choice C is incorrect.** $(32x + 8)^{2}$ implies a side of $32x + 8$, which is not obtained from adding $32$ to the perimeter of $4x$ and dividing by $4$.
**Choice D is incorrect.** $(32x + 32)^{2}$ likewise gives a side of $32x + 32$, which does not come from the correct computation of Q’s side $(4x + 32)/4 = x + 8$.
**Faster approach:** Add $32$ to the perimeter $4x$ to get $4x + 32$, divide by $4$ to get the new side $x + 8$, then square that side to get the area $(x + 8)^{2}$.'),
  ('7ac56b4c-97cd-5196-b455-93a39de4a678', 2, null, '**Choice C is correct.** Multiply the first equation by $5$: $5(3.5x + 1.2y) = 5(8)$ gives $17.5x + 6y = 40$, which is exactly the second equation. Because the two equations are the same line, every solution of one is also a solution of the other, so there are infinitely many solutions (all points on that line).
**Choice A is incorrect.** There is not exactly one solution because the equations are not two distinct intersecting lines; they are the same line, so they do not intersect at a single point.
**Choice B is incorrect.** A linear system of two equations in two variables cannot have exactly two solutions unless one allows nonstandard objects; here the equations either coincide, are parallel (zero solutions), or intersect once.
**Choice D is incorrect.** There are solutions (in fact every point on the line), so the system does not have zero solutions.
**Faster approach:** Check whether one equation is a scalar multiple of the other; if so, there are infinitely many solutions, if not and slopes are equal then none, otherwise exactly one.'),
  ('ea8b07f5-df4d-582a-8e8b-8c93022f24a0', null, array['2209']::text[], '**The correct answer is 2209.** The area of a circle is $A = πr^{2}$. Circle A has area $π(2x)^{2} = π \cdot 4x^{2}$. Circle B has area $π(94x)^{2} = π \cdot 8836x^{2}$. The ratio (area of B) ÷ (area of A) is $\frac{π \cdot 8836x^{2}}{π \cdot 4x^{2}}$$= \frac{8836}{4} = 2209$.
**Faster approach:** Compare radii: $\frac{94x}{2x} = 47$, so the linear scale factor is 47 and the area scale factor is $47^{2} =$ $2209$. This method avoids expanding squares immediately and is quicker for any similar problem.'),
  ('88b761b9-ffbe-5ea7-aec8-127256038a12', null, array['391']::text[], '**The correct answer is 391.** Since $g(23) = 0$, substitute $x = 23$ into $g(x) = (x + 17)(t - x)$ to get $(23 +$ $17)(t - 23) = 0$. Because $23 + 17 = 40 \ne 0$, it must be that $t - 23 = 0$, so $t = 23$. Now evaluate $g(0) = (0 +$ $17)(t - 0) = 17 \cdot t = 17 \cdot 23 = 391$.
**Faster approach:** Use the zero at $x = 23$ to conclude $t = 23$ immediately (the other factor $x + 17$ is not zero at $x = 23$), then compute $g(0) = 17 \cdot 23$ without expanding the expression.'),
  ('bd7f3b15-3790-527b-b447-cfe661623334', 3, null, '**Choice D is correct.** The center of a circle with diameter endpoints $(a,11)$ and $(a,d)$ is the midpoint of those points, which is $(a,(11 + d)/2)$. The given equation has center $(a,17)$, so $(11 + d)/2 = 17$. Solving gives $11 +$ $d = 34$ and $d = 23$, which matches choice D.
**Choice A is incorrect.** If $d = 5$ the midpoint would be $(a,(11 + 5)/2) = (a,8)$, not $(a,17)$, so that $d$ does not produce the given center.
**Choice B is incorrect.** If $d = 12$ the midpoint would be $(a,(11 + 12)/2) = (a,11.5)$, not $(a,17)$, so it is not correct.
**Choice C is incorrect.** If $d = 17$ the midpoint would be $(a,(11 + 17)/2) = (a,14)$, not $(a,17)$, so it does not match the circle’s center.
**Faster approach:** Use the midpoint formula immediately: set $(11 + d)/2 = 17$ and solve for $d$, which yields $d = 23$. This direct midpoint step works for any similar diameter/center problem.')
