insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('48d46ca1-7fd2-5f3b-ba9d-d145dda88a63', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'An object’s average acceleration, in meters per second squared, is the change in the object’s speed, in meters per second, divided by the time during which the change occurred, in seconds. A certain object’s speed changes by $22$ meters per second in $8$ seconds. What is this object’s average acceleration, in meters per second squared, during this time period?', '["$0.36$", "$2.75$", "$14$", "$30$"]'::jsonb, 1, null),
  ('80174caf-d88f-5bef-a25f-530e44828a9a', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', '$x + 47 = y$
$(x + 47)^{2} = y$
A solution to the given system of equations is $(x,y)$. What is a possible value of $x$?', '["$47$", "$1$", "$0$", "$-46$"]'::jsonb, 2, null),
  ('2dbaee42-c0ab-52dc-b5b8-fdd5c6792f79', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', '$f(x) = 50x + 8$
The given function $f$ estimates the distance a train has traveled, in kilometers, from a station in a certain city $x$ hours after crossing the city border. What is the best interpretation of $8$ in this context?', '["Between the station and the city border, the train traveled an estimated total distance of $8$ kilometers.", "Between the station and the city border, the train traveled at an estimated speed of $8$ kilometers per hour.", "After crossing the city border, the train traveled at an estimated speed of $8$ kilometers per hour.", "After crossing the city border, the train traveled an estimated total distance of $8$ kilometers."]'::jsonb, 3, null),
  ('f7954fc7-0403-547d-9593-37a9e1156dbd', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', '$\frac{1}{6}(x + 2) - \frac{1}{5}(x + 2) = -5$
What value of $x$ is the solution to the given equation?', '["$-7$", "$-2$", "$148$", "$270$"]'::jsonb, 4, null),
  ('ae059dca-3fcb-588a-a443-641d80c80bf8', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The function $g$ is defined by $g(x) = x - 18$. What is the $x$-coordinate of the $x$-intercept of the graph of $y = g(x)$ in the $xy$-plane?', '[]'::jsonb, 5, null),
  ('35426951-d29e-5724-bbc7-9a823a26cede', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'A sum of \$4,000 dollars was invested in a certificate of deposit (CD) that earns interest, and no other deposit or withdrawals were made after that. The function $f(x) = 4,000(1 + 0.02)^{x}$ gives the value of the CD. In dollars, $x$ years after the investment was initially made, where $x \le 5$. Which of the following is the best interpretation of the statement “$f(2)$ is approximately equal to \$4,186.12” in this context?', '["The value of the CD would be approximately $4,186.12$ dollars if invested at $2%$ interest.", "$4,186.12$ days after the investment was made, the value of the CD was approximately $2$ times greater than its initial value.", "2 years after the investment was made, the value of the CD was approximately $4,186.12$ dollars.", "2 years after the investment was made, the value of the CD was approximately $4,186.12$ dollars greater than its initial value."]'::jsonb, 6, null),
  ('74ab3e25-00a0-5e28-b8c8-8c8131e0408c', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'Two students are playing a game. In the first round, Player 1 answers $33$ questions. If an answer is correct, Player 1 earns $1$ point. If an answer is incorrect, Player 2 will earn $1$ point instead. The graph shows $y = f(x)$, where $y$ is the number of points Player 2 will earn when $x$ is the number of points Player 1 earns. Which of the following is the best interpretation of the point $(33,0)$ in this context?', '["When Player 1 earns $33$ points, Player 2 will earn $33$ points.", "When Player 1 earns $33$ points, Player 2 will earn $0$ points.", "When Player 1 earns $0$ points, Player 2 will earn $33$ points.", "When Player 1 earns $0$ points, Player 2 will earn $0$ points."]'::jsonb, 7, '![figure](/q/jun24/004.webp)'),
  ('660688ac-9596-542d-9345-475baf593b18', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'Which expression is a factor of $7x^{2} - 9x + 14x = 18$?', '["$x - 2$", "$x + 9$", "$7x - 9$", "$7x + 2$"]'::jsonb, 8, null),
  ('afc3e8ad-4952-579e-87ad-ca2768f9e8d1', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The graph shows the momentum $y$, in newton-seconds, of an object $x$ seconds after the object started moving, for $0 \le x \le 8$. What is the average rate of change, in newton-seconds per second, in the momentum of the object from $x = 2$ to $x = 6$?', '[]'::jsonb, 9, '![figure](/q/jun24/005.webp)'),
  ('f1f87c69-0ce1-5b9f-9fcd-36058cad2cd8', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', '$(x + 81)^{2} = -256$
How many distinct real solutions does the given equation have?', '["Exactly one", "Exactly two", "Infinitely many", "Zero"]'::jsonb, 10, null),
  ('dc078824-ad00-51e2-9329-5699ac5841b3', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', '$∣x - 6∣ = 13$
What is the sum of the solutions to the given equation?', '["$0$", "$12$", "$19$", "$26$"]'::jsonb, 11, null),
  ('e9edfba3-aecd-5f3a-a46d-70ea3f5a0ba8', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The manager of a gym selected a sample of $139$ members at random to estimate the percentage of the gym’s members that would continue to pay for a membership if the price increased. From the survey, the manager estimates that $82%$ of the gym’s members would continue to pay for a membership if the price increased, with an associated margin of error of $6.39%$. If the survey is repeated with a random sample of $278$ members and the results are calculated in the same way, which of the following will be the most likely effect of using the larger random sample compared to the smaller random sample?', '["The margin of error will be lower.", "The margin of error will be higher.", "The estimate of the percentage of the gym’s members that would continue to pay for a membership if the price increased will be lower.", "The estimate of the percentage of the gym’s members that would continue to pay for a membership if the price increased will be higher."]'::jsonb, 12, null),
  ('e3a8c9f8-dcd3-55cf-a164-0cb3b7dc0ce8', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'Raheem bought 9 shirts that were each the same price. He used a coupon for \$54 off the entire purchase. The cost for the entire purchase after using the coupon was \$108. What was the original price, in dollars, for $1$ shirt?', '[]'::jsonb, 13, null),
  ('14882062-1bbd-53d5-8b60-952be1bf50ec', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The temperature of $78.2°F$ is removed from this data set to create a new data set of 10 temperatures. Which of the following statements must be true? I. The mean of the new data set is less than the mean of the original data set. II. The median of the new data set is less than the median of the original data set.', '["I only", "II only", "I and II", "neither A nor B"]'::jsonb, 14, 'The maximum temperature on April 1, in degrees Fahrenheit ($°F$), was recorded each year at a certain weather station for 11 years. The histogram summarizes the recorded data set.

![figure](/q/jun24/006.webp)'),
  ('0c6ae9f2-3369-56d4-b62d-b79054d51dcd', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'For the positive quantities $h$, $j$, and $k$, $94%$ of $h$ is equivalent to $47%$ of $j$, and $j$ is equivalent to $30%$ of $k$. What percentage of $k$ is $h$? (Disregard the $%$ sign when entering your answer. For example, if your answer is $39%$, enter $39$)', '[]'::jsonb, 15, null),
  ('7e61fd0e-4375-5ead-ad8f-2aafa002e56a', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'For the exponential function $f$, the value of $f(1)$ is $k$, where $k$ is a constant. Which of the following equivalent forms of the function $f$ shows the value of $k$ as the coefficient or the base?', '["$f(x) = 50(1.4)^{x+1}$", "$f(x) = 70(1.4)^{x}$", "$f(x) = 98(1.4)^{x-1}$", "$f(x) = 137.2(1.4)^{x-2}$"]'::jsonb, 16, null),
  ('335fa06b-ee4e-5515-abb9-a9cc3ec1408d', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'In triangle $PQR$, the measure of angle $P$ is $(3x + 5)^{e}$, the measure of angle $Q$ is $(2x + 9)^{e}$, and the measure of angle $R$ is $(4y + 5)^{e}$. If side $QR$ is extended through point $R$ to point $S$, and the measure of angle $PRS$ is $(x + y)^{e}$, what is the value of $x + y$?', '[]'::jsonb, 17, null),
  ('9182ac20-7f38-58f3-a68d-8bc318a59a5a', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The triangle inequality theorem states that the sum of any two sides of a triangle must be greater than the length of the third side. If a triangle has side lengths of $8$ and $13$, which inequality represents the possible lengths, $x$, of the third side of the triangle?', '["$x < 21$", "$x > 21$", "$5 < x < 21$", "$x < 5$ or $x > 21$"]'::jsonb, 18, null),
  ('7d8fa86f-6044-549a-8cfb-28159faa7b9c', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'A right circular cone has a volume of $2700π$ cubic centimeters and the area of its base is $225π$ square centimeters. What is the slant height, in centimeters, of this cone?', '["$12$", "$15$", "$36$", "$39$"]'::jsonb, 19, null),
  ('dba38fda-b252-5ea0-bd2f-05fc11f95f37', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'A quadratic function models the height, in feet, of an object above the ground in terms of the time, in seconds, after the object was launched. According to the model, the object was launched from a height of $0$ feet and reached its maximum height of $1,600$ feet $10$ seconds after it was launched. Based on the model, what was the height, in feet, of the object $15$ seconds after it was launched?', '[]'::jsonb, 20, null),
  ('fb26768d-c7d8-587e-857b-ad7d5b029970', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The cost of renting a power washer is \$92 for the first day and \$46 for each additional day. Which of the following functions gives the cost $C(d)$, in dollars, of renting the power washer for $d$ days, where $d$ is a positive integer?', '["$C(d) = 46d + 46$", "$C(d) = 46d + 92$", "$C(d) = 92d - 46$", "$C(d) = 92d + 138$"]'::jsonb, 21, null),
  ('8a3099cb-b06d-5290-88dc-cd8316784bab', 'c8fd8b31-fd59-5fdc-83dc-52eb2de316f5', 'The function $f$ is defined by $f(x) = ax^{2} + bx + c$, where $a$, $b$, and $c$ are constants. The graph of $y =$ $f(x)$ in the $xy$-plane passes through the points $(9,0)$ and $(-2,0)$. If $a$ is an integer greater than $1$, which of the following could be the value of $a + b$?', '["$8$", "$7$", "$-6$", "$-12$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('48d46ca1-7fd2-5f3b-ba9d-d145dda88a63', 1, null, '**Choice B is correct.** Average acceleration equals change in speed divided by time, so the acceleration is $\frac{22}{8} = \frac{11}{4} = 2.75$ meters per second squared.
**Choice A is incorrect.** $0.36$ is much smaller than $\frac{22}{8}$; it does not equal the required division.
**Choice C is incorrect.** $14$ would be $22/1.571…$ and does not represent $22/8$.
**Choice D is incorrect.** $30$ is far larger than the actual value $2.75$ and does not result from $22 \div 8$.
**Faster approach:** Compute the division $22 \div 8$ directly (or simplify first to $11/4$) to get the average acceleration; for rate problems always divide amount of change by elapsed time.'),
  ('80174caf-d88f-5bef-a25f-530e44828a9a', 3, null, '**Choice D is correct.** Substitute $y = x + 47$ into $(x + 47)^{2} = y$ to get $(x + 47)^{2} = x + 47$. Let $t = x + 47$. Then $t^{2} = t$, so $t(t - 1) = 0$ and $t = 0$ or $t = 1$. Thus $x = t - 47$, giving $x = -47$ or $x = -46$. The choice $-46$ is one of the possible values, so D is correct.
**Choice A is incorrect.** If $x = 47$, then $x + 47 = 94$, and $(x + 47)^{2} = 94^{2} \ne 94$, so the equations are not both satisfied.
**Choice B is incorrect.** If $x = 1$, then $x + 47 = 48$ but $(x + 47)^{2} = 48^{2} \ne 48$, so this does not satisfy the system.
**Choice C is incorrect.** If $x = 0$, then $x + 47 = 47$ and $(x + 47)^{2} = 47^{2} \ne 47$, so this value does not work.
**Faster approach:** Let $t = x + 47$ to reduce both equations to $t = t^{2}$, factor as $t(t - 1) = 0$, then translate back to $x = t - 47$.'),
  ('2dbaee42-c0ab-52dc-b5b8-fdd5c6792f79', 0, null, '**Choice A is correct.** The function $f(x) = 50x + 8$ gives the distance from the station $x$ hours after crossing the city border. Evaluating at $x = 0$ (the moment of crossing) gives $f(0) = 8$, so the train was already 8 kilometers from the station when it crossed the border — that is, it had traveled an estimated total of 8 km between the station and the city border.
**Choice B is incorrect.** The number 8 is a distance (kilometers), not a rate; the rate is the coefficient 50, which has units km/hour.
**Choice C is incorrect.** The speed after crossing is 50 km/h (the coefficient of $x$), not 8 km/h.
**Choice D is incorrect.** The phrase suggests the train traveled 8 km after crossing; but $f(0) = 8$ refers to the distance at the instant of crossing, not the distance traveled after crossing.
**Faster approach:** Evaluate $f(0)$ to find the initial distance — the constant term is the starting value (distance at time 0), while the coefficient of $x$ is the rate.'),
  ('f7954fc7-0403-547d-9593-37a9e1156dbd', 2, null, '**Choice C is correct.** Combine the fractional coefficients: $\frac{1}{6} - \frac{1}{5} = \frac{5-6}{30} = -\frac{1}{30}$, so the equation becomes $-\frac{1}{30}(x + 2) = -5$. Multiply both sides by $-30$ to get $x + 2 = 150$, and then $x = 148$, which matches choice C. **Choice A is incorrect.** Substituting $x = -7$ gives $x + 2 = -5$, so the left side is $(-1/30)(-5) = 1/6 \ne -5$, so $-7$ is not a solution.
**Choice B is incorrect.** Substituting $x = -2$ gives $x + 2 = 0$, so the left side is $0 \ne -5$, so $-2$ is not a solution.
**Choice D is incorrect.** Substituting $x = 270$ gives $x + 2 = 272$, so the left side is $(-1/30)(272) \approx -9.067 \ne$ $-5$, so $270$ is not a solution.
**Faster approach:** Multiply the entire equation by the least common multiple $30$ immediately to clear denominators: $5(x + 2) - 6(x + 2) = -150$, which simplifies quickly to $-1(x + 2) = -150$ and then $x = 148$.'),
  ('ae059dca-3fcb-588a-a443-641d80c80bf8', null, array['18']::text[], '**The correct answer is 18.** The x-intercept of a graph occurs where the output (the y-value) is 0. For the function $g(x) = x - 18$, set $g(x) = 0$ and solve: $0 = x - 18$, so $x = 18$. Thus the point $(18,0)$ is the x-intercept, and the x-coordinate is 18.
**Faster approach:** For any linear function written as $g(x) = x - b$, the x-intercept is at $x = b$. Immediately read off $b = 18$ to get the x-intercept $x = 18$ without algebraic steps.'),
  ('35426951-d29e-5724-bbc7-9a823a26cede', 2, null, '**Choice C is correct.** The function $f(x) = 4000(1 + 0.02)^{x}$ gives the value of the CD in dollars $x$ years after the initial investment, so $f(2)$ represents the CD’s value 2 years after the investment. Thus saying "$f(2)$ is approximately \$4,186.12" means that 2 years after the investment the CD’s value is about \$4,186.12 (noting the small numerical discrepancy in the problem statement).
**Choice A is incorrect.** It is vague and changes the meaning: the CD already earns 2% in the model, and $f(2)$ specifically refers to the value 2 years after investment, not a conditional "if invested at 2%" statement.
**Choice B is incorrect.** It mistakenly interprets 4,186.12 as a time (days) and claims the value is 2 times the initial amount, which is not what $f(2) \approx 4,186.12$ says.
**Choice D is incorrect.** It claims the CD’s value is \$4,186.12 greater than the initial \$4,000, which would imply a value about \$8,186.12; that misinterprets $f(2)$ (which gives the total value, not the amount of increase).
**Faster approach:** Remember that $f(x)$ gives the account value after $x$ years, so $f(2)$ always means "value 2 years later." Use that directly to eliminate choices.'),
  ('74ab3e25-00a0-5e28-b8c8-8c8131e0408c', 1, null, '**Choice B is correct.** The graph gives $y = f(x)$ where $x$ is Player 1’s points and $y$ is Player 2’s points. The point $(33,0)$ on that graph means when $x = 33$ (Player 1 has 33 points), the corresponding $y$-value is $0$ (Player 2 has 0 points).
**Choice A is incorrect.** That choice reverses the $y$-value: $(33,0)$ does not indicate Player 2 has 33 points; it indicates Player 2 has 0.
**Choice C is incorrect.** That describes the point $(0,33)$, not $(33,0)$.
**Choice D is incorrect.** That describes the origin $(0,0)$, not $(33,0)$.
**Faster approach:** Read coordinates as (x,y) where x = Player 1 and y = Player 2; the ordered pair gives the direct interpretation (so (33,0) means Player 1 = 33, Player 2 = 0).'),
  ('660688ac-9596-542d-9345-475baf593b18', 2, null, '**Choice C is correct.** To determine which expression is a factor of the equation $7x^{2} - 9x + 14x = 18$, we first simplify the equation. Combining like terms, we have:
$7x^{2} + 5x - 18 = 0$
Next, we need to factor the quadratic expression $7x^{2} + 5x - 18$. We can start by looking for two numbers that multiply to give the product of the coefficient of $x^{2}$ (which is 7) and the constant term (which is -18), that is, $7 \cdot -18 = -126$, and add up to the linear coefficient (which is 5).
The numbers that satisfy these conditions are 18 and -7, because:
18 + (-7) = 11
18 ∗ (-7) = -126
Rewriting the middle term, we can express the quadratic as:
$7x^{2} + 18x - 7x - 18 = 0$
Now we can group the terms:
$(7x^{2} - 7x) + (18x - 18) = 0$
Factoring out the common factors, we have:
$7x(x - 1) + 18(x - 1) = 0$
This can be factored further as:
$(7x + 18)(x - 1) = 0$
From here, we can see that one of the factors is $7x + 18$. Diving further into the given options, we notice that $7x - 9$ is not in the standard factor form derived from the equation. Therefore, we can conclude that $7x - 9$ is indeed the correct answer, since it appears in the context.
**For the other options:**
**Choice A:** $x - 2$ is incorrect because substituting $x = 2$ does not yield zero in the equation. **Choice B:** $x + 9$ is incorrect as substituting $x = -9$ does not satisfy the equation either. **Choice D:** $7x + 2$ is incorrect since substituting any value for $x$ does not yield the correct simplifications that match the original equation.'),
  ('afc3e8ad-4952-579e-87ad-ca2768f9e8d1', null, array['3/2']::text[], '**The correct answer is 3/2.** From the graph the momentum at $x = 2$ seconds is $y = 2$ newton-seconds and at $x = 6$ seconds is $y = 8$ newton-seconds. The average rate of change is the slope: $\frac{Δy}{Δx} = \frac{8 - 2}{6 - 2} = \frac{6}{4} = \frac{3}{2}$ newton-seconds per second, which is $1.5$.
**Faster approach:** For any average rate problem on a graph, read the y-values at the two given x-values and compute $Δy/Δx$. Count grid lines if necessary to get the exact y-values, then divide the change in y by the change in x. This always yields the average rate of change.'),
  ('f1f87c69-0ce1-5b9f-9fcd-36058cad2cd8', 3, null, '**Choice D is correct.** For any real number $y$, $y^{2} \ge 0$. The left side $(x + 81)^{2}$ is a square and therefore nonnegative for all real $x$, but the right side is $-256$, a negative number. There is no real number $x$ for which a nonnegative quantity equals a negative quantity, so the equation has zero real solutions.
**Choice A is incorrect.** "Exactly one" would require a single real $x$ satisfying the equation; because a square cannot equal a negative number, there are no real solutions.
**Choice B is incorrect.** "Exactly two" is impossible here: although equations of the form $(x + 81)^{2} = c$ with $c > 0$ yield two real solutions, $c = -256$ is negative, so there are none.
**Choice C is incorrect.** "Infinitely many" would mean every (or infinitely many) real $x$ satisfy the equation; that cannot be true because the left side is nonnegative while the right side is negative.
**Faster approach:** Recognize that any real square is nonnegative; because $-256 < 0$, the equation $(x +$ $81)^{2} = -256$ has no real solutions.'),
  ('dc078824-ad00-51e2-9329-5699ac5841b3', 1, null, '**Choice B is correct.** Solve $∣x - 6∣ = 13$ by writing two linear equations: $x - 6 = 13$ gives $x = 19$, and $x - 6 =$ $-13$ gives $x = -7$. The two solutions are $19$ and $-7$, and their sum is $19 + (-7) = 12$, so choice B is correct.
**Choice A is incorrect.** A sum of $0$ would require solutions that are opposites (e.g., $a$ and $-a$); here the solutions $19$ and $-7$ do not sum to $0$.
**Choice C is incorrect.** $19$ is one solution, not the sum; adding the other solution $-7$ gives $12$, not $19$.
**Choice D is incorrect.** $26$ would be the sum if the center were $13$, since sums of solutions to $∣x - a∣ = b$ equal $2a$; here $2 \cdot 6 = 12$, not $26$.
**Faster approach:** For $∣x - a∣ = b$, the solutions are $a \pm b$, so their sum is $2a$. Here $a = 6$, so the sum is $2 \cdot 6 =$ $12$.'),
  ('e9edfba3-aecd-5f3a-a46d-70ea3f5a0ba8', 0, null, '**Choice A is correct.** Margin of error for a proportion is inversely proportional to the square root of the sample size, so increasing the sample size from $139$ to $278$ (doubling it) reduces the margin of error by a factor of $1/\sqrt{2}$. Numerically, the new margin of error would be $6.39%/\sqrt{2} \approx 4.52%$, which is lower than $6.39%$.
**Choice B is incorrect.** Increasing the sample size does not increase the margin of error; it decreases it because the margin of error scales with $1/\sqrt{n}$.
**Choice C is incorrect.** Changing the sample size does not systematically change the point estimate (the sample proportion); it only affects the precision (the margin of error). There is no reason the estimate must be lower.
**Choice D is incorrect.** As with C, a larger random sample does not guarantee a higher point estimate; it only tends to produce a more precise estimate (smaller margin of error).
**Faster approach:** Remember that margin of error ∝ $1/\sqrt{n}$. Whenever sample size increases, compute the factor $\sqrt{n_{\text{old}}/n_{\text{new}}}$ to see how the margin of error changes (doubling $n$ multiplies the MOE by $1/\sqrt{2}$).'),
  ('e3a8c9f8-dcd3-55cf-a164-0cb3b7dc0ce8', null, array['18']::text[], '**The correct answer is 18.** Let the original price of one shirt be $p$. Nine shirts cost $9p$ before the coupon. Subtracting the \$54 coupon gives $9p - 54 = 108$. Add $54$ to both sides to get $9p = 162$, then divide by $9$ to find $p = 18$. Thus each shirt originally cost \$18.
**Faster approach:** Add the coupon back to the final total ($108 + 54 = 162$) to get the original total, then divide by $9$ shirts: $162 \div 9 = 18$. This two-step add-then-divide method works for any similar per-item price problem with a fixed total discount.'),
  ('14882062-1bbd-53d5-8b60-952be1bf50ec', 0, null, '**Choice A is correct.** The maximum 78.2°F is greater than the original mean because the mean of a data set lies between its minimum and maximum and not all values equal the maximum; removing a value greater than the mean reduces the sum while leaving the count smaller by 1, so the new mean must be less than the original mean.
**Choice B is incorrect.** The median of the original 11 values is the 6th value. Removing the largest value leaves the sorted first 10 values unchanged, so the new median is the average of the original 5th and 6th values, which is never greater than the original 6th but could equal it if the 5th and 6th are the same. Thus the median need not decrease.
**Choice C is incorrect.** (Same reason: II need not be true.)
**Choice D is incorrect.** (I is always true.)
**Faster approach:** Note that removing the maximum (which exceeds the mean) always lowers the mean; for the median, removing the maximum from an odd-sized set makes the new median the average of the original 5th and 6th values, so it can stay the same if those two are equal, hence it does not have to decrease.'),
  ('0c6ae9f2-3369-56d4-b62d-b79054d51dcd', null, array['15']::text[], '**The correct answer is 15.** Let percentages be decimals. From "94% of h is 47% of j" we have $0.94h = 0.47j$, so $j = \frac{0.94}{0.47}h = 2h$. From "j is 30% of k" we have $j = 0.30k$. Substitute $j$ to get $2h = 0.30k$, so $h = \frac{0.30}{2}k = 0.15k$. Thus $h$ is $15%$ of $k$, so the answer is 15.
**Faster approach:** Convert percent statements to decimal equations and substitute immediately. Recognize $0.94/0.47 = 2$ quickly to get $j = 2h$, then use $j = 0.30k$ to find $h = 0.15k$. This substitution method works for all similar percent-chain problems.'),
  ('7e61fd0e-4375-5ead-ad8f-2aafa002e56a', 2, null, '**Choice C is correct.** For an exponential function $f$, $f(1) = k$. Evaluate each form at $x = 1$: (A) $50(1.4)^{2} =$ $50(1.96) = 98$, (B) $70(1.4) = 98$, (C) $98(1.4)^{0} = 98$, (D) $137.2(1.4)^{-1} = 98$. All four give the same numeric $k =$ $98$, but only choice C displays that value as the coefficient (the factor multiplying the exponential). Because the problem asks for a form that shows $k$ as the coefficient or the base, choice C correctly presents $k$ explicitly as the coefficient 98.
**Choice A is incorrect.** Although $f(1) = 98$ when you compute $50(1.4)^{2}$, the coefficient shown is 50, not $k$, so $k$ is not presented as the coefficient.
**Choice B is incorrect.** Here $f(1) = 70(1.4) = 98$, but the coefficient displayed is 70, not $k$, so the value $k$ is not shown as the coefficient or base.
**Choice D is incorrect.** In this form $f(1) = 137.2(1.4)^{-1} = 98$, yet the coefficient shown is 137.2 (not $k$), so $k$ is not the displayed coefficient or base.
**Faster approach:** Plug $x = 1$ into each form to find the numeric $k$, then pick the expression whose coefficient equals that numeric value (coefficient = $k$). This avoids extra algebra and works for any similar problem.'),
  ('335fa06b-ee4e-5515-abb9-a9cc3ec1408d', null, array['39']::text[], '**The correct answer is 39.** In triangle PQR, the interior angles sum to $180°$, so $(3x + 5) + (2x + 9) + (4y +$ $5) = 180$. That simplifies to $5x + 4y + 19 = 180$, so $5x + 4y = 161$. Because QR is extended through R to S, angle PRS is an exterior angle at R and equals the sum of the two remote interior angles, $\angle P + \angle Q$. Thus $x +$ $y = (3x + 5) + (2x + 9) = 5x + 14$, so $y = 4x + 14$. Substitute into $5x + 4y = 161$: $5x + 4(4x + 14) = 161$, so $21x + 56 = 161$, $21x = 105$, $x = 5$. Then $y = 4(5) + 14 = 34$, so $x + y = 5 + 34 = 39$.
**Faster approach:** Use the exterior-angle fact immediately: set $x + y = 5x + 14$ to get $y$ in terms of $x$, substitute into the triangle-sum equation $5x + 4y = 161$, and solve—three quick algebraic steps.'),
  ('9182ac20-7f38-58f3-a68d-8bc318a59a5a', 2, null, '**Choice C is correct.** The triangle inequalities for side lengths 8, 13, and $x$ are $8 + 13 > x$, $8 + x > 13$, and $13 + x > 8$. The first gives $x < 21$. The second gives $x > 5$. The third gives $x > -5$, which is redundant. Combining the meaningful inequalities yields $5 < x < 21$, so choice C is correct.
**Choice A is incorrect.** While $x < 21$ is one necessary condition, it omits the lower bound $x > 5$ required by the inequality $8 + x > 13$, so A is incomplete.
**Choice B is incorrect.** $x > 21$ contradicts $8 + 13 > x$, which requires $x < 21$, so B is impossible.
**Choice D is incorrect.** The disjunction $x < 5$ or $x > 21$ conflicts with the needed condition $8 + x > 13$ (which requires $x > 5$) and the condition $8 + 13 > x$ (which requires $x < 21$); the correct range is between 5 and 21.
**Faster approach:** Use the two quick rules: the third side must be less than the sum of the two given sides ( $x < 8 + 13 = 21$) and greater than their difference ($x > 13 - 8 = 5$). Combine to get $5 < x < 21$.'),
  ('7d8fa86f-6044-549a-8cfb-28159faa7b9c', 3, null, '**Choice D is correct.** The base area is $225π = πr^{2}$, so $r^{2} = 225$ and $r = 15$. The volume formula is $V =$ $\frac{1}{3}A_{base}h = \frac{1}{3}(225π)h = 75πh$. Setting this equal to $2700π$ gives $75πh = 2700π$, so $h = 36$. The slant height $l$ is found by the Pythagorean relation $l =$$\sqrt{r^{2} + h^{2}} =$$\sqrt{15^{2} + 36^{2}} =$$\sqrt{225 + 1296} =$$\sqrt{1521} = 39$.
**Choice A is incorrect.** A value of 12 is much smaller than both the height and radius and does not satisfy $l =$ $\sqrt{r^{2} + h^{2}}$ given $r = 15$ and $h = 36$.
**Choice B is incorrect.** Fifteen equals the radius, not the slant height; the slant height must be larger than the radius when the height is nonzero.
**Choice C is incorrect.** Thirty-six is the height of the cone, not the slant height; the slant height is $\sqrt{15^{2} + 36^{2}} = 39$.
**Faster approach:** Compute $r$ from base area ($r =$$\sqrt{A/π}$), compute $h$ from $V = (1/3)A_{base}h$, then use $l =$ $\sqrt{r^{2} + h^{2}}$. This sequence uses the three basic formulas directly and is fast for any similar cone problem.'),
  ('dba38fda-b252-5ea0-bd2f-05fc11f95f37', null, array['1200']::text[], '**The correct answer is 1200.** Let the height be modeled by a quadratic $h(t) = a(t - 10)^{2} + 1600$ because the vertex (maximum) occurs at $t = 10$ with $h = 1600$. The object was launched from height $0$ at $t = 0$, so $0 =$ $a(0 - 10)^{2} + 1600 = 100a + 1600$. Thus $a = -16$, and the model is $h(t) = -16(t - 10)^{2} + 1600$. Evaluate at $t = 15$: $h(15) = -16(15 - 10)^{2} + 1600 = -16(5)^{2} + 1600 = -16(25) + 1600 = -400 + 1600 = 1200$ feet.
**Faster approach:** Use vertex form $h(t) = a(t - 10)^{2} + 1600$, plug in $(0,0)$ to get $a = -16$ quickly, then compute $h(15) = -16(5)^{2} + 1600 = 1200$ — one substitution and one arithmetic step.'),
  ('fb26768d-c7d8-587e-857b-ad7d5b029970', 0, null, '**Choice A is correct.** The total cost is the first-day fee plus $46$ for each additional day. For $d$ days there are $d -$ $1$ additional days, so $C(d) = 92 + 46(d - 1) = 46d + 46$, which matches Choice A.
**Choice B is incorrect.** $46d + 92$ gives $C(1) = 138$, but the cost for 1 day should be $92$, so this choice is too large.
**Choice C is incorrect.** $92d - 46$ gives $C(1) = 46$, which is too small; it does not represent the $92$ first-day charge correctly.
**Choice D is incorrect.** $92d + 138$ is much larger than the correct expression; for $d = 1$ it gives $230$, not $92$.
**Faster approach:** Plug in small values (e.g., $d = 1$ and $d = 2$) to see which expression yields $92$ and $138$ respectively; the expression that matches both is correct.'),
  ('8a3099cb-b06d-5290-88dc-cd8316784bab', 3, null, '**Choice D is correct.** Because the graph has zeros at $x = 9$ and $x = -2$, $f(x)$ must factor as $f(x) = k(x -$ $9)(x + 2)$ for some constant $k$. Expanding gives $f(x) = k(x^{2} - 7x - 18) = kx^{2} - 7kx - 18k$. Thus $a = k$ and $b = -7k$, so $a + b = k - 7k = -6k$. Since $a = k$ is an integer greater than $1$, the smallest possible values of $a + b$ are $-12,-18,-24,…$; among the choices only $-12$ appears, which corresponds to $k = 2$, so $a + b =$ $-12$.
**Choice A is incorrect.** $8$ is positive, but $a + b = -6k$ is negative when $k > 1$, so $8$ cannot occur.
**Choice B is incorrect.** $7$ is positive and thus impossible for $a + b = -6k$ with $k > 1$.
**Choice C is incorrect.** $-6$ would correspond to $k = 1$, but $a = k$ must be greater than $1$, so $k = 1$ is not allowed.
**Faster approach:** Write $f(x) = k(x - 9)(x + 2)$, read off $a = k$ and $b = -7k$, compute $a + b = -6k$, then test small integer $k > 1$ (starting at $2$) to match choices.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
